def simple_calculator(num1: float, operator: str, num2: float) -> str | float:
    """
    Performs basic arithmetic operations (+, -, *, /) on two numbers.

    Args:
        num1: The first number.
        operator: The arithmetic operator as a string.
        num2: The second number.

    Returns:
        The result of the operation or 'Error' if division by zero occurs.
    """
    if operator == '+':
        return add_numbers(num1, num2)
    elif operator == '-':
        return subtract_numbers(num1, num2)
    elif operator == '*':
        return multiply_numbers(num1, num2)
    elif operator == '/':
        return divide_numbers(num1, num2)
    else:
        """
        Handles invalid operators.
        """
        return 'Error: Invalid operator'

def add_numbers(a: float, b: float) -> float:
    """
    Adds two numbers together.
    """
    return a + b

def subtract_numbers(a: float, b: float) -> float:
    """
    Subtracts the second number from the first.
    """
    return a - b

def multiply_numbers(a: float, b: float) -> float:
    """
    Multiplies two numbers.
    """
    return a * b

def divide_numbers(a: float, b: float) -> str | float:
    """
    Divides the first number by the second.
    Handles division by zero by returning 'Error'.
    """
    if b == 0:
        return 'Error'
    return a / b

def is_valid_number(num: any) -> bool:
    """
    Checks if the input is a valid number (integer or float).
    """
    return isinstance(num, (int, float))

