def fibonacci_sequence(n: int) -> list[int]:
    """
    Generates the first 'n' numbers of the Fibonacci sequence.

    The sequence starts with 0 and 1.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input 'n' must be a non-negative integer.")

    if n == 0:
        return []
    elif n == 1:
        return [0]
    else:
        sequence = [0, 1]
        _generate_remaining_fibonacci(sequence, n - 2)
        return sequence

def _generate_remaining_fibonacci(sequence: list[int], count: int):
    """
    Appends the remaining Fibonacci numbers to the given sequence.

    This is a helper function for fibonacci_sequence.
    """
    for _ in range(count):
        next_fib = _calculate_next_fibonacci(sequence)
        sequence.append(next_fib)

def _calculate_next_fibonacci(sequence: list[int]) -> int:
    """
    Calculates the next Fibonacci number based on the last two in the sequence.
    """
    return sequence[-1] + sequence[-2]

def _validate_input_type(n: int):
    """
    Validates that the input 'n' is an integer.
    """
    if not isinstance(n, int):
        raise TypeError("Input 'n' must be an integer.")

def _validate_input_non_negative(n: int):
    """
    Validates that the input 'n' is a non-negative number.
    """
    if n < 0:
        raise ValueError("Input 'n' must be non-negative.")

def _get_initial_sequence(n: int) -> list[int]:
    """
    Returns the initial part of the Fibonacci sequence based on 'n'.
    """
    if n == 0:
        return []
    elif n == 1:
        return [0]
    else:
        return [0, 1]

