def caesar_cipher_encrypt(text, shift):
    """
    Encrypts a given string using a Caesar cipher.

    Only alphabetic characters are shifted, wrapping around the alphabet.
    Case is preserved.
    """
    encrypted_text = ""
    for char in text:
        encrypted_text += _encrypt_char(char, shift)
    return encrypted_text

def _encrypt_char(char, shift):
    """
    Encrypts a single character using a Caesar cipher.

    Handles both uppercase and lowercase letters, preserving their case.
    Non-alphabetic characters are returned unchanged.
    """
    if 'a' <= char <= 'z':
        return _shift_lowercase(char, shift)
    elif 'A' <= char <= 'Z':
        return _shift_uppercase(char, shift)
    else:
        return char

def _shift_lowercase(char, shift):
    """
    Shifts a lowercase character by the given amount.

    Performs a circular shift within the lowercase alphabet ('a' through 'z').
    """
    start = ord('a')
    return chr(start + (ord(char) - start + shift) % 26)

def _shift_uppercase(char, shift):
    """
    Shifts an uppercase character by the given amount.

    Performs a circular shift within the uppercase alphabet ('A' through 'Z').
    """
    start = ord('A')
    return chr(start + (ord(char) - start + shift) % 26)

def _is_alphabetical(char):
    """
    Checks if a character is an alphabetical letter (a-z or A-Z).
    """
    return 'a' <= char <= 'z' or 'A' <= char <= 'Z'

def _get_shifted_char(char, base, shift_amount):
    """
    Calculates the shifted character based on its base (e.g., 'a' for lowercase).
    """
    return chr(base + (ord(char) - base + shift_amount) % 26)

